import {cities,cityById} from '../data/cities.js';
import {hobbyNames,unitNames} from '../data/catalog.js';
import {careers} from '../data/careers.js';
import {draw,hashSeed,weighted} from '../engine/probability.js';
export function createPlayer({seed='人生',city='random',gender='随机',name='',birthYear=2000,debug=false}={}){
 let rng=hashSeed(seed);const random=()=>{const d=draw(rng);rng=d.rng;return d.value;};const pick=a=>a[Math.floor(random()*a.length)];const n=(a,b)=>Math.floor(a+random()*(b-a+1));
 const chosen=city==='random'?pick(cities):cityById(city);const randomSurname=pick(['王','李','张','刘','陈','杨','赵','周','徐','孙']);const inputName=name.trim().slice(0,12);const surname=/^[\u3400-\u9fff]/u.test(inputName)?inputName[0]:randomSurname;
 const hidden=Object.fromEntries(['luck','network','learning','professional','risk','business','enterprise','research','gaming','sport','music','acting','gambling','addiction','credit'].map(k=>[k,n(20,85)]));hidden.credit=80;hidden.addiction=0;hidden.gambling=10;
 const innate=Object.fromEntries(hobbyNames.map(h=>[h,n(-15,85)]));
 const parents=['父亲','母亲'].map((role,i)=>{const c=weighted(careers.map(c=>({c,weight:chosen.parentCareerWeights[c.id]??1})),random()).c;return {id:'parent'+i,role,name:(i?pick(['林','吴','郑','黄']):surname)+pick(i?['秀英','雅琴','玉兰','丽娟']:['建国','志强','建华','国平']),age:n(24,38),career:c.id,industry:c.industry,income:Math.round(c.baseSalary*chosen.wage),education:n(2,5),personality:pick(['温和','严厉','开朗','谨慎']),health:n(65,95),hobby:pick(hobbyNames),unit:pick(unitNames),city:chosen.id,relationship:75,alive:true,retired:false,estate:n(50000,300000)};});
 const s={version:1,id:hashSeed(seed).toString(36)+'-'+hashSeed(seed+chosen.id+name).toString(36),seed:String(seed),rng:0,debug,name:inputName||surname+pick(['知远','星河','一诺','子安','景行','雨桐','思齐','念初']),gender:gender==='随机'?pick(['男','女']):gender,birthYear,age:0,birthCity:chosen.id,city:chosen.id,cityHistory:[{city:chosen.id,startAge:0,endAge:null,reason:'出生与成长'}],familiarity:100,adaptation:0,education:0,major:'通用',qualifications:[],schoolHistory:[],clubs:[],career:null,careerLevel:0,careerYears:0,careerHistory:[],retired:false,effort:'balanced',sideJob:null,relationshipStatus:'单身',partner:null,children:[],parents,stats:{health:n(65,95),intelligence:n(30,85),eq:n(30,80),happiness:n(50,85),reputation:0},hidden,innateHobbies:innate,hobbies:{...innate},personality:{adventure:0,cautious:0,frugal:0,workaholic:0,independent:0,helpful:0,social:0},aspiration:'暂时没有明确目标',cash:0,salary:0,bonus:0,debt:0,company:0,properties:[],investments:{deposit:0,fund:0,stock:0,venture:0},tags:[],counts:{moves:0,careerChanges:0,startups:0,gambles:0,wins:0,losses:0,children:0,marriages:0,help:0},echoUsage:{},memories:[],socialHistory:[],npcs:[],scheduled:[],history:[],audit:[],debugLogs:[],totals:{income:0,peak:0,happiness:0,health:0,years:0},world:{market:'normal',housing:'normal',year:birthYear},pending:null,dead:false,deathReason:'',rewindUsed:false,study:1,fans:0};s.rng=rng;
 s.history.push({age:0,year:birthYear,city:chosen.id,eventId:'birth',category:'家庭',title:'来到这个世界',text:`你出生在${chosen.name}。${parents[0].name}和${parents[1].name}抱着你，商量了很久你的名字。关于将来的事，家里人有不少盼头，但此刻只希望你平安长大。`,choice:null,background:[],effects:[]});return s;
}
